class CountDown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self  # итератор сам по себе

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        val = self.current
        self.current -= 1
        return val

for n in CountDown(3):
    print(n)  # 3, 2, 1

def countdown(start):
    while start > 0:
        yield start
        start -= 1

def infinite():
