def robust():
    try:
        while True:
            yield "работает"
    except ValueError:
        yield "поймал ValueError"
    except Exception:
        yield "поймал другое"

gen = robust()
print(next(gen))              # "работает"
print(gen.throw(ValueError))  # "поймал ValueError"
print(next(gen))              # "работает" (продолжило!)
print(gen.throw(RuntimeError))# "поймал другое"

def infinite():
    try:
        while True:
            yield "tick"
    finally:
        print("Очистка ресурсов!")

gen = infinite()
next(gen)
gen.close()  # вызывает GeneratorExit внутри, срабатывает finally

def gen_numbers():
    yield from range(1, 11)

def filter_even(gen):
    for x in gen:
        if x % 2 == 0:
            yield x

def square(gen):
    for x in gen:
        yield x ** 2

pipeline = square(filter_even(gen_numbers()))
list(pipeline)  # [4, 16, 36, 64, 100]

def coroutine(func):
    @wraps(func)
    def primer(*args, **kwargs):
        gen = func(*args, **kwargs)
        next(gen)
        return gen
    return primer

@coroutine
def grep(pattern):
    print(f"Ищем {pattern}")
    while True:
        line = yield
        if pattern in line:
            print(line)

g = grep("python")
g.send("hello world")
g.send("python is great")  # python is great
